function allWordsLineUp(text: string, words: string[]): number[] {
  const w = words[0].length, total = w * words.length;
  const need = new Map<string, number>();
  for (const x of words) need.set(x, (need.get(x) ?? 0) + 1);
  const out: number[] = [];
  for (let i = 0; i + total <= text.length; i++) {
    const seen = new Map<string, number>();
    let ok = true;
    for (let j = 0; j < words.length; j++) {
      const t = text.slice(i + j * w, i + (j + 1) * w);
      const c = (seen.get(t) ?? 0) + 1;
      if (c > (need.get(t) ?? 0)) { ok = false; break; }
      seen.set(t, c);
    }
    if (ok) out.push(i);
  }
  return out;
}

