class Solution:
    def allWordsLineUp(self, text: str, words: List[str]) -> List[int]:
        w, m = len(words[0]), len(words)
        need = Counter(words)
        out = []
        for i in range(len(text) - w * m + 1):
            seen = Counter()
            for j in range(m):
                t = text[i + j * w:i + (j + 1) * w]
                seen[t] += 1
                if seen[t] > need[t]:
                    break
            else:
                out.append(i)
        return out

