function allWordsLineUp(text: string, words: string[]): number[] {
  const w = words[0].length, m = words.length, n = text.length;
  const need = new Map<string, number>();
  for (const x of words) need.set(x, (need.get(x) ?? 0) + 1);
  const out: number[] = [];
  for (let o = 0; o < w; o++) {
    let left = o, used = 0;
    const have = new Map<string, number>();
    for (let right = o; right + w <= n; right += w) {
      const t = text.slice(right, right + w);
      if (!need.has(t)) { have.clear(); used = 0; left = right + w; continue; }
      have.set(t, (have.get(t) ?? 0) + 1);
      used++;
      while (have.get(t)! > need.get(t)!) {
        const d = text.slice(left, left + w);
        have.set(d, have.get(d)! - 1);
        used--;
        left += w;
      }
      if (used === m) {
        out.push(left);
        const d = text.slice(left, left + w);
        have.set(d, have.get(d)! - 1);
        used--;
        left += w;
      }
    }
  }
  return out.sort((a, b) => a - b);
}

